const aType=id=>AS.types.find(t=>t.id===id);
const visQ=(t,ans)=>t.q.filter(q=>!q.show||((ans||{})[q.show.q]!=null&&q.show.v.includes(ans[q.show.q])));
function qScore(q,a){if(a==null||a==="")return null;if(q.t==="yn"||q.t==="choice"){const o=q.opts.find(x=>x[0]===a);return o?o[1]:null}if(q.t==="scale")return (num(a,1)-1)/4;if(q.t==="matrix"){const vs=q.rows.map(r=>a&&a[r]!=null?(num(a[r],1)-1)/4:null).filter(x=>x!=null);return vs.length?vs.reduce((s,x)=>s+x,0)/vs.length:null}if(q.t==="file")return a?1:0;return null}
function qAnswered(q,a){if(q.t==="matrix")return !!a&&q.rows.every(r=>a[r]!=null);return a!=null&&a!==""}
function bandOf(t,score){const b=t.bands.slice().sort((x,y)=>y[1]-x[1]).find(x=>score>=x[1])||t.bands[t.bands.length-1];return{n:b[0],tone:b[2]}}
function scoreOf(t,ans,passOv){const rows=visQ(t,ans).map(q=>({q,a:(ans||{})[q.id],p:qScore(q,(ans||{})[q.id]),done:qAnswered(q,(ans||{})[q.id])}));const sc=rows.filter(r=>r.q.w>0);const miss=rows.filter(r=>!r.done&&(r.q.t!=="text"||false)&&r.q.req!==false&&r.q.t!=="text").map(r=>r.q.q);const W=sc.reduce((s,r)=>s+r.q.w,0)||1,P=sc.reduce((s,r)=>s+r.q.w*(r.p==null?0:r.p),0);const score=Math.round(P/W*100);return{score,band:bandOf(t,score),pass:score>=(passOv!=null?passOv:t.pass),missing:miss,rows,type:t.id}}
function autoAnswers(t,seed,bias,noise){const r=RNG("asm"+seed+t.id);const ans={};const nz=noise||.55;const pickLvl=()=>Math.max(0,Math.min(1,bias+(r()-.5)*nz));
 for(let k=0;k<3;k++){visQ(t,ans).forEach(q=>{if(ans[q.id]!=null)return;const L=pickLvl();if(q.t==="yn"||q.t==="choice"){ans[q.id]=q.opts.slice().sort((a,b)=>Math.abs(a[1]-L)-Math.abs(b[1]-L))[0][0]}else if(q.t==="scale")ans[q.id]=Math.max(1,Math.min(5,Math.round(1+4*L)));else if(q.t==="matrix"){const m={};q.rows.forEach(x=>m[x]=Math.max(1,Math.min(5,Math.round(1+4*pickLvl()))));ans[q.id]=m}else if(q.t==="file")ans[q.id]=L>.3?q.id+"-evidence.pdf":"";else ans[q.id]="Covered in the supplier questionnaire."})}return ans}
const ASSESSX=window.ASSESSX=window.ASSESSX||{};
