function prefill(){const T=AS.take,t=aType(T.tid),a=autoAnswers(t,T.subject,.72),vis=visQ(t,a);let n=0;vis.forEach(q=>{if(T.answers[q.id]==null||T.answers[q.id]===""){if(q.t==="text"&&!a[q.id])return;T.answers[q.id]=a[q.id];if(!T.prefill.includes(q.id))T.prefill.push(q.id);n++}});audit("AI prefilled assessment",t.n+": "+n+" answers");toast(n+" answers drafted from evidence. Review each one before you submit.","info");repaintTake()}
