 const entry={at:"Oct 7",by:by+(beh?" (on behalf of "+(holdersOf(it)[0]||needRoles(it)[0])+")":""),act:{approve:"Approved",conditions:"Approved with conditions",return:"Returned",info:"Asked for information",reject:"Rejected"}[act],note};
 const g=gatesOf(it);const lowAdv=g.filter(x=>x.a.mode==="advisory"&&x.st==="fail"),dis=(act==="approve"||act==="conditions")&&(it.ai.d==="reject"||it.ai.d==="return")||act==="reject"&&it.ai.d==="approve"&&it.ai.conf>=.8;
 if(v.override||lowAdv.length&&(act==="approve"||act==="conditions")||dis){const reason=v.override||v.comment||"No reason given";it.ovr=reason;lowAdv.forEach(x=>{if(x.r&&window.ASSESSX&&ASSESSX.override)ASSESSX.override(x.r.id,reason)});entry.note=(entry.note?entry.note+" · ":"")+"Override: "+reason;audit("overrode "+(lowAdv.length?"advisory assessment":"AI recommendation"),it.id+": "+reason)}
 it.st=st;it.turn=it.age+.5;it.by=by;it.hist.push(entry);AX.dec[id]=Object.assign(AX.dec[id]||{},{st:it.st,turn:it.turn,by:it.by,ovr:it.ovr,hist:it.hist,dlg:it.dlg});audit((beh?"approved on behalf: ":"")+({approve:"approved",conditions:"approved with conditions",return:"returned",info:"requested information on",reject:"rejected"})[act],it.id+" · "+it.title+(note?" · "+note:""));
